// Vector art anchored to the mirrored palm, both in the scene and camera preview.
export function createTimeAura(panel,video){
 const make=()=>{const el=document.createElement('div');el.className='time-aura';el.hidden=true;const ticks=Array.from({length:48},(_,i)=>`<path transform="rotate(${i*7.5} 100 100)" d="M100 9v${i%4?6:12}"/>`).join('');el.innerHTML=`<svg viewBox="0 0 200 200" aria-hidden="true"><g class="aura-outer"><circle cx="100" cy="100" r="90"/><circle cx="100" cy="100" r="83"/>${ticks}</g><g class="aura-inner"><circle cx="100" cy="100" r="68"/><path d="M100 27 163 136 37 136Z M100 173 37 64 163 64Z"/><path d="M51 51H149V149H51Z" transform="rotate(22.5 100 100)"/></g><circle cx="100" cy="100" r="35"/><path class="aura-gem" d="M100 77 113 100 100 123 87 100Z"/></svg><span class="aura-caption"></span>`;return el;};
 const stage=make(),preview=make();stage.classList.add('aura-stage');preview.classList.add('aura-preview');document.body.append(stage);const wrap=document.createElement('div');wrap.className='hand-video-wrap';video.before(wrap);const countdown=document.createElement("div");countdown.className="hand-countdown";countdown.hidden=true;countdown.setAttribute("aria-label","时间宝石倒数");wrap.append(video,preview,countdown);
 return {countdown(action){stage.hidden=preview.hidden=true;countdown.hidden=false;countdown.textContent=String(Math.ceil((1-action.hold)*3));countdown.style.left=action.palm.x*100+'%';countdown.style.top=action.palm.y*100+'%';},show(action,text){countdown.hidden=true;const p=action.palm;if(!p){this.hide();return;}for(const el of [stage,preview]){el.hidden=false;el.style.setProperty('--charge',1);el.querySelector('.aura-caption').textContent=text;}stage.style.left=p.x*innerWidth+'px';stage.style.top=p.y*innerHeight+'px';stage.style.width=Math.max(130,Math.min(340,action.width*innerWidth*2))+'px';preview.style.left=p.x*100+'%';preview.style.top=p.y*100+'%';preview.style.width=Math.max(35,action.width*200)+'%';},hide(){stage.hidden=preview.hidden=countdown.hidden=true;}};
}
